import random

MOD = 1_000_000_007

def solve_optimal(n):
    ways = [1, 1, 2]
    for i in range(3, n + 1):
        ways.append((ways[-1] + ways[-2] + ways[-3]) % MOD)
    return ways[n] % MOD

def solve_brute(n):
    def count(left):
        if left < 0:
            return 0
        if left == 0:
            return 1
        return count(left - 1) + count(left - 2) + count(left - 3)
    return count(n) % MOD

def gen(rng, size):
    return [rng.randint(0, {"tiny": 4, "small": 10, "large": 16}[size])]

def validate(args):
    return isinstance(args[0], int) and 0 <= args[0] <= 20
